CREATE TABLE P_LEW_CORE.T_POS_RECEIPTLINE_COUPON_PROMOTION_DISCOUNT_2 (
   coupon_promo_sid                    NUMBER(38,0)    COMMENT 'unique identifier of the coupon_promotion (surrogate key)',
   src_coupon_promo_nr                 VARCHAR(100)    COMMENT 'identifier of the coupon_promotion within LidlPlus/SCRM source system SCRM: external_id',
   client_id                           NUMBER(38,0)    NOT NULL COMMENT 'DWH-Mandant_2; FK auf CLIENT',
   loc_sid                             NUMBER(38,0)    NOT NULL COMMENT 'Filiale; FK auf LOCATION_2; SAP-CAR: z_ds_zpdx_tlogf.plant; WAWI-DWH: t_ejr_receiptline.store_id',
   item_sid                            NUMBER(38,0)    COMMENT 'Verkaufs-Artikel_2; FK auf ITEM_2; SAP-CAR: z_ds_zpdx_tlogf.materialnumber; WAWI-DWH: t_ejr_receiptline.item_id',
   curr_sid                            NUMBER(38,0)    COMMENT 'Waehrung; FK auf CURRENCY; SAP-CAR: z_ds_zpdx_tlogf.transcurrency; WAWI-DWH: -',
   uom_sid                             NUMBER(38,0)    COMMENT 'Mengeneinheit; FK auf UNIT_2 OF MEASUREMENT; SAP-CAR: z_ds_zpdx_tlogf.salesuom; WAWI-DWH: -',
   register_id                         NUMBER(38,0)    NOT NULL COMMENT 'Kassennummer; WAWI-DWH: t_ejr_receiptline.pos_terminal_id',
   receipt_id                          NUMBER(38,0)    NOT NULL COMMENT 'Bon-Nummer; WAWI-DWH: t_ejr_receiptline.orig_receipt_nr_ejr',
   receipt_dt                          DATE            NOT NULL COMMENT 'Bon-Datum; WAWI-DWH: t_ejr_receiptline.dat_formdate',
   receipt_tmsp                        TIMESTAMP_NTZ(9) COMMENT 'Bon-Zeitstempel; WAWI-DWH: t_ejr_receiptline.dat_formdate + time_receipt_ejr',
   receiptline_nr                      NUMBER(38,0)    NOT NULL COMMENT 'Laufende Nummer auf Bon; WAWI-DWH: t_ejr_receiptline.orig_receipt_serial_nr_ejr',
   transaction_type_cd                 VARCHAR(20)     COMMENT 'WAWI-DWH: t_ejr_receiptline.transactiontype_id',
   timezone_id                         NUMBER(38,0)    COMMENT 'Zeitzone; WAWI-DWH: t_ejr_receiptline.timezone_cd',
   ean_barcode                         VARCHAR(100)    COLLATE 'en-ci' COMMENT 'EAN_2-Barcode; WAWI-DWH: t_ejr_receiptline.barcode',
   main_item_grp_cd                    VARCHAR(20)     COMMENT 'MainItemGroup; WAWI-DWH: t_ejr_receiptline.mainitemgrp_id',
   weight_item_fg                      NUMBER(38,0)    COMMENT 'Kennzeichen Gewichtsartikel; WAWI-DWH: t_ejr_receiptline.weight_item_fg',
   turnover_relevant_fg                NUMBER(38,0)    COMMENT 'Umsatzrelevante Position; ',
   sales_fg                            NUMBER(38,0)    COMMENT 'Position ist eine_2 Verkaufszeile (1=ja; 0=nein); case when transaction_type_cd in (100,101,102,103,170,172,180,182) then 1 else 0',
   deposit_fg                          NUMBER(38,0)    COMMENT 'Position ist eine_2 Pfandzeile (1=ja; 0=nein); case when transaction_type_cd in (120,121,122,123,220,221,222,223) then 1 else 0',
   discount_sid                        NUMBER(38,0)    COMMENT 'Rabattgrund - Code; WAWI-DWH: t_ejr_receiptline.discount_id',
   discount_val                        NUMBER(18,5)    COMMENT 'gewaehrter Rabatt; WAWI-DWH: t_ejr_receiptline.val_discount_ejr',
   discount_base_val                   NUMBER(18,5)    COMMENT 'Originalpreis ohne Rabattierung; WAWI-DWH: val_discount_base_ejr',
   discount_weight_qty                 NUMBER(18,5)    COMMENT 'Menge, auf die der Rabatt angewendet wird (fuer Gewichtsartikel); WAWI-DWH: qty_discount_pos_ejr',
   discount_piece_qty                  NUMBER(18,5)    COMMENT 'Anzahl der Artikel_2, auf die der Rabatt angewendet wird (fuer Mengenartikel); WAWI-DWH: qty_discount_hq_ejr',
   vat_pct_val                         NUMBER(18,5)    COMMENT 'Mehrwertsteuer Prozentsatz; WAWI-DWH: t_ejr_receiptline.pct_vat_ejr',
   vat_val                             NUMBER(18,5)    COMMENT 'Mehrwertsteuerbetrag; WAWI-DWH: t_ejr_receiptline.val_vat_ejr',
   tax_class_cd                        VARCHAR(20)     COMMENT 'WAWI-DWH: t_ejr_receiptline.type_vat_ejr',
   void_fg                             NUMBER(38,0)    COMMENT 'Position ist eine_2 Stornozeile (1=ja; 0=nein); case when transaction_type_cd in (171,173) then 1 else 0',
   receiptline_voided                  NUMBER(38,0)    COMMENT 'stornierte Bon-Zeile; WAWI-DWH: t_ejr_receiptline.parent_line_nr_ejr',
   receiptline_voided_by               NUMBER(38,0)    COMMENT 'storniert durch Bon-Zeile; WAWI-DWH: t_ejr_receiptline.voided_by_line_nr_ejr',
   return_fg                           NUMBER(38,0)    COMMENT 'Position ist eine_2 Retourenzeile (1=ja; 0=nein); case when transaction_type_cd in (140,141,142,143) then 1 else 0',
   return_reason_cd                    VARCHAR(20)     COMMENT 'Rueckgabegrund; WAWI-DWH: t_ejr_receiptline.return_reason_cd_ejr',
   dwh_cal_dt                          DATE            NOT NULL COMMENT 'businessdaydate; WAWI-DWH: t_ejr_receiptline.dat_formdate',
   dwh_load_id                         NUMBER(38,0)    NOT NULL COMMENT 'Identifier des letzten Ladelaufs, der den Datensatz eingfuegt oder veraendert hat',
   dwh_created                         TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Zeitstempel der Ersteinfuegung des Datensatzes ins DWH',
   dwh_updated                         TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Zeitstempel der letzten Aenderung des Datensatzes im DWH'
)
COMMENT = '$Revision: 0000 $. table contains selected infromation from picked receiptlines related to the LidlPlus-Discount relevant Receiptline-Key''s identified by LidlPlus pattern detection on src_discount_nr';
